proxmox-hookscript.content_template:
#!/usr/bin/env bash
set -euo pipefail

vmid=${1:?missing VMID}
phase=${2:?missing phase}
inside=/data/mounts/{{mount_name}}
published={{shared_mount_root}}/{{mount_name}}
published_ro={{shared_mount_read_only_root}}/{{mount_name}}
helper=/usr/local/libexec/proxmenux-oci-mount-publish
waiter=/usr/local/libexec/proxmenux-oci-mount-wait
unit="proxmenux-rclone-publish-$vmid.service"

unpublish() {
  local target=$1
  if mountpoint -q "$target"; then
    umount "$target" || umount -l "$target"
  fi
}

stop_waiter() {
  systemctl stop "$unit" >/dev/null 2>&1 || true
  systemctl reset-failed "$unit" >/dev/null 2>&1 || true
}

case "$phase" in
  pre-start)
    install -d -m 0755 "$published" "$published_ro"
    if ! mountpoint -q {{shared_mount_root_parent}}; then
      mount --bind {{shared_mount_root_parent}} {{shared_mount_root_parent}}
    fi
    mount --make-rshared {{shared_mount_root_parent}}
    stop_waiter
    unpublish "$published_ro"
    unpublish "$published"
    ;;
  post-start)
    stop_waiter
    systemd-run --quiet --collect --unit="$unit" -- \
      "$waiter" "$vmid" "$inside" "$published" "$published_ro" "$helper"
    ;;
  pre-stop|post-stop)
    stop_waiter
    unpublish "$published_ro"
    unpublish "$published"
    ;;
esac
